type Net=ReturnType<typeof useCollectorNetwork>;
type Kind='single'|'collection';
type SaleType='fixed'|'auction';
type Condition=NonNullable<ListingItem['condition']>;
type ConditionInput={mode:''|'Raw'|'CGC';grade:string;label:string;printing:string};
type PublicValue=Condition&{issueId:number;fmv:number;updatedAt:string;sourceName:string;sourceUrl:string;fresh:boolean};
type Props={net:Net;vault:Vault;gate:()=>boolean;notice:(s:string)=>void;openCollection:()=>void;onAddComic?:()=>void;addComicOpen?:boolean;onSeller:(handle:string)=>void;onMessage:(id:string,title:string)=>void;onReport:(id:string)=>void;marketIssue:number|null;clearIssue:()=>void};
const dollars=(cents:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
const labels=['Universal','Signature Series','Qualified','Restored','Conserved'];
const blankCondition:ConditionInput={mode:'',grade:'',label:'',printing:''};
function cleanCondition(input:ConditionInput|undefined):Condition|undefined{
 if(!input?.mode||!grades.includes(input.grade)||!['First printing','Later printing'].includes(input.printing))return;
 const label=input.mode==='Raw'?'Raw':input.label;
 if(input.mode==='CGC'&&!labels.includes(label))return;
 return {mode:input.mode,grade:input.grade,label:label as Condition['label'],printing:input.printing as Condition['printing']};
}
function matchingValue(item:ListingItem,values:PublicValue[]){
 const issue=linkedCatalogIssue(item);
 if(!issue||!item.condition)return;
 const key=marketKey({issueId:issue.id,...item.condition});
 return values.find(v=>v.fresh&&freshValue(v.updatedAt)&&marketKey(v)===key);
}
function summarize(items:ListingItem[],values:PublicValue[]):ListingValuation{
 const matches=items.map(item=>matchingValue(item,values)).filter((v):v is PublicValue=>!!v);
 const total=matches.reduce((sum,v)=>sum+Math.round(v.fmv*100),0);
 return {total:matches.length===items.length&&items.length?total:null,knownTotal:matches.length?total:null,pricedCount:matches.length,totalCount:items.length,status:!matches.length?'unavailable':matches.length===items.length?'complete':'partial',asOf:matches.length?matches.map(v=>v.updatedAt).sort()[0]:null,sourceNames:[...new Set(matches.map(v=>v.sourceName))]};
}
function Valuation({detail=false}:{value?:ListingValuation;detail?:boolean}){
 return <div className="mp-value mp-value-coming"><div><span>MARKET VALUE</span><strong>Coming soon</strong></div><small>FMV for Raw and CGC comics is being prepared.</small>{detail&&<p>The seller sets the asking price. It is separate from fair market value; no market estimate is being displayed.</p>}</div>;
}
function remaining(endAt:string,now:number){
 const seconds=Math.max(0,Math.ceil((Date.parse(endAt)-now)/1000));
 if(!seconds)return 'Ending / refresh';
 const days=Math.floor(seconds/86400),hours=Math.floor(seconds%86400/3600),minutes=Math.floor(seconds%3600/60),secs=seconds%60;
 return days?`${days}d ${hours}h ${minutes}m`:`${hours}h ${String(minutes).padStart(2,'0')}m ${String(secs).padStart(2,'0')}s`;
}
const initialDraft={title:'',description:'',price:'',shipping:'0',cert:'',duration:'72',increment:'5.00',fulfillment:'shipping' as ListingFulfillment,pickupCity:'',pickupState:'',owned:false,usa:false};
function deliveryLabel(listing:Listing){return listing.fulfillment==='pickup'?'Local pickup only':listing.fulfillment==='both'?'Shipping or local pickup':'USA shipping'}

