 const [draft,setDraft]=useState({...initialDraft}),[resumeDraft,setResumeDraft]=useState(false),[trade,setTrade]=useState(false),[tradeBookIds,setTradeBookIds]=useState<string[]>([]),[tradeQuery,setTradeQuery]=useState(''),[tradePage,setTradePage]=useState(0);
 const addBefore=useRef<{ids:Set<string>;actor:string}|null>(null),sawAddModal=useRef(false),tradeAttempt=useRef<{key:string;requestId:string}|null>(null);
