 useEffect(()=>{setEditor(false);setDetailId(null);setTrade(false);setResumeDraft(false);setDraft({...initialDraft});setBookIds([]);setPhotos([]);setConditions({});addBefore.current=null;tradeAttempt.current=null},[me?.id]);
 useEffect(()=>{setNow(Date.now());const timer=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(timer)},[]);
